/* A local offer book and HTLC workbench. It never reads keys or submits transactions. */
(() => {
  'use strict';
  const C=()=>globalThis.NodusTradeCore,T=(key,p)=>globalThis.NodusTradeText(key,p),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const KEY='nodus-observatory-trade-book-v2',LEGACY_KEY='nodus-observatory-trade-book-v1',MAX=512*1024;
  let legacyRaw=null;
  let root,offers=[],active=null,tab='details',simulation=null,message='',storageMessage='',deleteId='',busy=false,importVersion=0;
  const secrets=new Map();
  let form={name:'',side:'sell_nodus',nodusAmount:'1000',usdtAmount:'10',token:'',maker:{nodus:'',bsc:''},taker:{nodus:'',bsc:''}};
  const b=(label,action,disabled=false)=>`<button type="button" class="button" data-trade-action="${action}"${disabled?' disabled':''}>${esc(T(label))}</button>`;
  const input=(id,label,value)=>`<label class="trade-field" for="trade-${id}"><span>${esc(T(label))}</span><input id="trade-${id}" value="${esc(value)}" autocomplete="off" spellcheck="false" maxlength="160"></label>`;
  const selected=()=>offers.find(x=>x.id===active)||null;
  const stamp=n=>new Date(n*1000).toISOString().replace('T',' ').replace('.000Z',' UTC');
  function read(){try{const raw=localStorage.getItem(KEY);if(raw===null){storageMessage='';return [];}if(raw.length>MAX)throw Error('size');const x=JSON.parse(raw);if(x.schema!=='nodus-trade/book-v2'||!Array.isArray(x.offers)||x.offers.length>50||Object.keys(x).some(k=>!['schema','offers'].includes(k)))throw Error('schema');const list=x.offers.map(C().validate);if(new Set(list.map(o=>o.id)).size!==list.length)throw Error('duplicate');storageMessage='';return list;}catch{storageMessage='Stored offers could not be read. Existing data was retained.';return null;}}
  function save(offer){const current=read();if(!current){offers=[...offers.filter(x=>x.id!==offer.id),offer];return;}const old=current.find(x=>x.id===offer.id);if(old&&C().exportOffer(old)!==C().exportOffer(offer))throw Error('The same trade ID already has different terms.');if(!old&&current.length>=50)throw Error('The offer list is full (50). Export and delete an older offer.');const next=old?current:[...current,offer],raw=JSON.stringify({schema:'nodus-trade/book-v2',offers:next});try{if(raw.length>MAX)throw Error('size');localStorage.setItem(KEY,raw);storageMessage='';}catch{storageMessage='Storage is unavailable. Export the public offer and private recovery file.';}offers=next;}
  function capture(){if(!root)return;for(const key of ['name','side','nodusAmount','usdtAmount','token']){const el=root.querySelector('#trade-'+key);if(el)form[key]=el.value;}for(const party of ['maker','taker'])for(const chain of ['nodus','bsc']){const el=root.querySelector('#trade-'+party+'-'+chain);if(el)form[party][chain]=el.value;}}
  function error(e){message=e.code?T('Check the input: {code} ({field}).',{code:T(e.code),field:e.field||'—'}):T(e.message||'invalid_schema');}
  function download(name,text,type='application/json'){let url;try{url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();message=T('Download created.');}catch{error({code:'download_failed'});}finally{if(url)URL.revokeObjectURL(url);}}
  function choose(id){++importVersion;active=id;simulation=null;tab='details';message='';deleteId='';}
  function formHTML(){return `<details class="panel trade-create"><summary>${T('New offer')}</summary><div class="trade-form">${input('name','Name',form.name)}<label class="trade-field" for="trade-side"><span>${T('Direction')}</span><select id="trade-side"><option value="sell_nodus"${form.side==='sell_nodus'?' selected':''}>${T('Sell NODUS')}</option><option value="buy_nodus"${form.side==='buy_nodus'?' selected':''}>${T('Buy NODUS')}</option></select></label>${input('nodusAmount','NODUS amount',form.nodusAmount)}${input('usdtAmount','TEST-USDT amount',form.usdtAmount)}<div class="trade-wide">${input('token','Test token contract address (BSC 97)',form.token)}</div><p class="trade-wide trade-asset-note">${T('Use the deployed MockUsdt address on BSC testnet. TEST-USDT has 18 decimals, is freely minted for testing, and has no monetary value. BNB pays network fees.')}</p>${['maker','taker'].map(p=>`<fieldset><legend>${T(p==='maker'?'Maker':'Taker')}</legend>${input(p+'-nodus','Nodus EVM address (32 bytes)',form[p].nodus)}${input(p+'-bsc','BSC address (20 bytes)',form[p].bsc)}</fieldset>`).join('')}<p class="trade-wide">${T('Both parties and both receiving addresses are fixed before either deposit.')}</p><div class="trade-wide trade-buttons">${b('Create offer','create',busy)}</div></div></details>`;}
  function bookHTML(){return `<section class="panel trade-book"><div class="trade-section-head"><h2>${T('My offers')} <small>${offers.length}/50</small></h2><div class="trade-buttons">${b('Create example','example',busy)}<label class="button trade-file">${T('Import offer / recovery')}<input id="trade-import" type="file" accept=".json,application/json"></label></div></div><p>${T('Offers stay in this browser. Share a public offer file with the other party.')}</p>${offers.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>${T('Name / direction')}</th><th>${T('Amounts')}</th><th></th></tr></thead><tbody>${offers.map(o=>`<tr${o.id===active?' class="trade-selected"':''}><td><strong>${esc(o.name)}</strong><span>${T(o.side==='sell_nodus'?'Sell NODUS':'Buy NODUS')}</span></td><td class="mono">${esc(o.nodusAmount)} NODUS<br>${esc(o.usdtAmount)} TEST-USDT</td><td><button class="button" data-trade-open="${o.id}">${T('Open')}</button><button class="button trade-quiet" data-trade-delete="${o.id}">${T('Delete')}</button></td></tr>`).join('')}</tbody></table></div>`:`<div class="trade-empty">${T('No offers yet.')}</div>`}${deleteId?`<div class="notice amber"><span>${T('Delete this offer?')}</span>${b('Keep','keep')}${b('Confirm deletion','delete')}</div>`:''}</section>`;}
  function details(o){return `<div class="trade-buttons">${b('Export public offer','export')}${b('Export private recovery','recovery',!secrets.has(o.id))}${b('Export transaction plan','plan')}</div><p class="trade-secret-note">${T(secrets.has(o.id)?'The secret is available only in this session. Export the recovery file before closing.':'Import the private recovery file to restore the maker secret.')}</p><p>${T('The recovery file contains the secret. Keep it private; it is not included in public offers or browser storage.')}</p><div class="trade-parties">${['maker','taker'].map(p=>`<section><h3>${T(p==='maker'?'Maker':'Taker')}</h3><span>NODUS</span><code>${esc(o[p].nodus)}</code><span>BNB Smart Chain</span><code>${esc(o[p].bsc)}</code></section>`).join('')}</div><dl class="trade-meta"><dt>${T('Quote asset')}</dt><dd>TEST-USDT · BSC 97 · 18 ${T('decimals')}</dd><dt>${T('Test token contract')}</dt><dd>${esc(o.asset.token)}</dd><dt>${T('Network fees')}</dt><dd>BNB / tBNB</dd><dt>${T('Trade ID')}</dt><dd>${esc(o.id)}</dd><dt>${T('Hashlock')}</dt><dd>${esc(o.hashlock)}</dd><dt>${T('Maker refund')}</dt><dd>${stamp(o.makerRefundAt)}</dd><dt>${T('Taker refund')}</dt><dd>${stamp(o.takerRefundAt)}</dd></dl><p>${T('Deadlines use UTC and start when the offer is created: 24 hours for the maker, 12 hours for the taker.')}</p>`;}
  function simHTML(o){const s=simulation;return `<div class="trade-section-head"><strong class="trade-badge">${T('Simulation only')}</strong>${b(s?'Reset simulation':'Start simulation','start',busy||!secrets.has(o.id))}</div><p>${T('The maker claims the shorter lock first. The taker then uses the revealed secret to claim the longer lock.')}</p>${s?`<p>${T('Simulated time')}: <time>${stamp(s.now)}</time></p><div class="trade-legs">${s.legs.map((leg,i)=>`<section class="trade-leg"><span class="trade-step">${i+1}</span><h3>${leg.chain==='nodus'?'NODUS':'TEST-USDT · BSC'}</h3>${leg.chain==='bsc'&&leg.status==='empty'?`<p>${T(leg.allowanceUnits===leg.amountUnits?'Exact token amount approved':'Token approval is required before locking')}</p>`:''}<strong>${T(leg.status[0].toUpperCase()+leg.status.slice(1))}</strong><p>${T(leg.funder==='maker'?'Maker':'Taker')} → ${T(leg.recipient==='maker'?'Maker':'Taker')}</p><div class="trade-buttons">${leg.chain==='bsc'?b('Approve exact test token amount','approve:'+i,busy||leg.status!=='empty'||leg.allowanceUnits===leg.amountUnits):''}${b(i?'Lock taker funds':'Lock maker funds','lock:'+i,busy||leg.status!=='empty'||leg.chain==='bsc'&&leg.allowanceUnits!==leg.amountUnits||i===1&&s.legs[0].status!=='locked')}${b(i?'Maker claims':'Taker claims','claim:'+i,busy||leg.status!=='locked'||i===0&&!s.secretRevealed)}${b(i?'Refund taker':'Refund maker','refund:'+i,busy||leg.status!=='locked'||s.now<leg.refundAt)}</div></section>`).join('')}</div><p class="trade-badge">${T(s.secretRevealed?'Secret revealed by first claim':'Secret not revealed')}</p>${s.legs.every(x=>x.status==='claimed')?`<p class="trade-complete">${T('Both legs settled.')}</p>`:''}<div class="trade-buttons">${b('Test a wrong secret','wrong',busy||s.legs[1].status!=='locked')}${b('Advance to taker deadline','advance-taker',busy||s.now>=o.takerRefundAt)}${b('Advance to maker deadline','advance-maker',busy||s.now>=o.makerRefundAt)}</div><ol class="trade-trace">${s.events.map(e=>`<li>${esc(e.action)} · ${stamp(e.now)}</li>`).join('')}</ol>`:''}<p>${T('A simulation does not verify deposits on either network.')}</p>`;}
  function contractsHTML(){const mainnet=C().BSC_MAINNET_USDT;return `<p>${T('These are complete compiled contracts for the named testnets. Deployment and wallet execution are separate steps.')}</p><div class="trade-legs">${Object.entries(globalThis.NodusTradeContracts.contracts).map(([chain,c])=>`<section class="trade-leg"><h3>${chain==='nodus'?'NODUS':chain==='bsc'?'TEST-USDT · BSC 97':T('Free test token · BSC 97')}</h3><p>${T('Pinned compiler')}: <code>${esc(c.compiler)}</code></p><p>${T('Address size')}: ${c.addressBytes} B</p>${chain==='bsc'?`<p>${T('Deploy the test token first. Pass its contract address to the swap constructor. Token approval is required before locking; send no BNB as the trade amount.')}</p>`:chain==='mockUsdt'?`<p>${T('MockUsdt is a freely minted test token, not real USDT and not redeemable. Its faucet is only for testnet experiments.')}</p>`:''}<div class="trade-buttons">${b('Download source','source:'+chain)}${b('Download ABI','abi:'+chain)}${b('Download bytecode','bytecode:'+chain)}</div><pre tabindex="0">${esc(c.source)}</pre></section>`).join('')}</div><p>${T('Before the maker reveals the secret, independently verify the two confirmed locks: network, code, trade ID, parties, amounts, hash and deadlines.')}</p><p>${T('Each refund requires a transaction after its deadline. Network fees are separate from the trade amounts.')}</p><details class="trade-mainnet-reference"><summary>${T('Mainnet USDT reference · information only')}</summary><p>${T('The future mainnet asset is Binance-Peg USDT on BNB Smart Chain (56), with 18 decimals. It is a third-party representation of USDT. Mainnet offers and transactions are not enabled here.')}</p><code>${esc(mainnet.token)}</code></details>`;}
  function render(){if(!root)return;const o=selected();root.innerHTML=`<div class="trade-workbench"><header class="trade-heading"><span class="eyebrow">${T('TESTNET WORKBENCH')}</span><h1>${T('Prepare a NODUS / USDT swap')}</h1><p>${T('Create buy and sell offers, rehearse both chain legs, and export the actual contracts.')}</p><div class="trade-buttons"><span class="trade-badge">${T('Nodus testnet')}</span><span class="trade-badge">${T('TEST-USDT · BSC testnet · 97')}</span></div></header><div class="notice amber trade-notice">${T('Local testnet workbench with a shared advertisement board and BSC wallet requests. Full two-chain execution requires Nodus network and wallet support.')}</div><p id="trade-message" role="status">${esc(message)}</p>${storageMessage?`<p class="notice amber">${T(storageMessage)}</p>`:''}${legacyRaw!==null?`<div class="notice amber trade-legacy"><p>${T('Old BNB offers are preserved separately. They are not converted into USDT offers.')}</p>${b('Export old BNB offers','legacy')}</div>`:''}${formHTML()}${bookHTML()}<section class="panel trade-detail"><div class="trade-tabs" role="tablist">${['details','simulation','contracts','network','board'].map((k,i)=>`<button role="tab" aria-selected="${tab===k}" data-trade-tab="${k}">${T(['Offer details','Rehearse swap','Contracts','Network trade','Shared offers'][i])}</button>`).join('')}</div>${tab==='network'||tab==='board'?'<div id="trade-live-panel"></div>':tab==='contracts'?contractsHTML():!o?`<p>${T('Choose an offer to continue.')}</p>`:tab==='simulation'?simHTML(o):details(o)}</section></div>`;bind();if(tab==='network'||tab==='board')globalThis.NodusTradeLive?.mount(root.querySelector('#trade-live-panel'),{mode:tab,offer:o,secret:()=>o&&secrets.get(o.id),draft:()=>{capture();return C().copy(form);},onDraft:fields=>{form=C().copy(fields);tab='details';message=T('Reservation copied to a draft. Review addresses and create a fresh offer with a new secret.');render();const create=root.querySelector('.trade-create');if(create)create.open=true;}});else globalThis.NodusTradeLive?.unmount();}
  async function act(action){if(busy)return;capture();busy=true;try{const o=selected();if(action==='create'||action==='example'){
      const fields=action==='example'?{name:T('Example swap · fictional addresses'),side:'sell_nodus',nodusAmount:'1000',usdtAmount:'10',asset:C().copy(C().EXAMPLE_ASSET),maker:{nodus:'0x'+'11'.repeat(32),bsc:'0x'+'22'.repeat(20)},taker:{nodus:'0x'+'33'.repeat(32),bsc:'0x'+'44'.repeat(20)}}:{name:form.name,side:form.side,nodusAmount:form.nodusAmount,usdtAmount:form.usdtAmount,maker:C().copy(form.maker),taker:C().copy(form.taker),asset:{kind:'bep20',chainId:97,token:form.token,decimals:18,symbol:'TEST-USDT'}};
      const x=await C().create(fields);save(x.offer);secrets.set(x.offer.id,x.secret);choose(x.offer.id);message=T('Offer created. Export the private recovery file.');
    }else if(action==='legacy'){if(legacyRaw!==null)download('nodus-trade-legacy-bnb-book-v1.json',legacyRaw);}
    else if(action==='export')download('nodus-trade-'+o.id.slice(2,14)+'.json',C().exportOffer(o));
    else if(action==='recovery')download('PRIVATE-nodus-trade-'+o.id.slice(2,14)+'.json',await C().recovery(o,secrets.get(o.id)));
    else if(action==='plan')download('nodus-trade-plan.json',JSON.stringify(C().plan(o),null,2)+'\n');
    else if(action==='start'){simulation=C().start(o);message='';}
    else if(action==='keep')deleteId='';
    else if(action==='delete'){const current=read();if(current){const next=current.filter(x=>x.id!==deleteId);localStorage.setItem(KEY,JSON.stringify({schema:'nodus-trade/book-v2',offers:next}));offers=next;secrets.delete(deleteId);if(active===deleteId){active=null;simulation=null;}deleteId='';message=T('Deleted.');}}
    else if(/^(source|abi|bytecode):/.test(action)){const [kind,chain]=action.split(':'),a=globalThis.NodusTradeContracts.contracts[chain];if(kind==='source')download(a.name+'.sol',a.source,'text/plain');if(kind==='abi')download(a.name+'.abi.json',JSON.stringify(a.abi,null,2)+'\n');if(kind==='bytecode')download(a.name+'.creation.hex',a.creation+'\n','text/plain');}
    else{let cmd=action,options={secret:secrets.get(o.id)};if(action==='advance-taker'||action==='advance-maker'){cmd='advance';options.now=o[action==='advance-taker'?'takerRefundAt':'makerRefundAt'];}else if(action==='wrong'){cmd='claim:1';options.secret='0x'+'99'.repeat(32);options.actor='maker';}else{const [kind,i]=action.split(':');options.actor=kind==='claim'?simulation.legs[Number(i)].recipient:simulation.legs[Number(i)].funder;}simulation=await C().step(o,simulation,cmd,options);message=T('Simulation advanced.');}
    }catch(e){error(e);}finally{busy=false;render();}}
  function bind(){root.querySelectorAll('[data-trade-action]').forEach(el=>el.onclick=()=>act(el.dataset.tradeAction));root.querySelectorAll('[data-trade-open]').forEach(el=>el.onclick=()=>{capture();choose(el.dataset.tradeOpen);render();});root.querySelectorAll('[data-trade-delete]').forEach(el=>el.onclick=()=>{capture();deleteId=el.dataset.tradeDelete;render();});root.querySelectorAll('[data-trade-tab]').forEach(el=>el.onclick=()=>{capture();tab=el.dataset.tradeTab;render();});root.querySelector('#trade-import').onchange=async event=>{const serial=++importVersion,file=event.target.files?.[0];if(!file)return;try{if(file.size>C().MAX_BYTES)throw {code:'file_too_large'};const text=await file.text();if(serial!==importVersion)return;const raw=JSON.parse(text);if(raw?.schema==='nodus-trade/offer-v1'||raw?.schema==='nodus-trade/recovery-v1'||raw?.schema==='nodus-trade/book-v1')throw {code:'legacy_bnb_offer'};let result;if(raw.schema===C().RECOVERY)result=await C().importRecovery(text);else result={offer:C().importOffer(text)};if(serial!==importVersion)return;save(result.offer);if(result.secret)secrets.set(result.offer.id,result.secret);choose(result.offer.id);message=T('Imported.');}catch(e){error(e);}render();};}
  globalThis.NodusTrade=Object.freeze({mount(target){capture();root=target;try{legacyRaw=localStorage.getItem(LEGACY_KEY);if(legacyRaw!==null&&legacyRaw.length>MAX)legacyRaw=null;}catch{legacyRaw=null;}if(!offers.length){const saved=read();if(saved)offers=saved;}render();},capture,getState:()=>C().copy({offers,active,tab,simulation,storageMessage}),getOffer:()=>selected()&&C().copy(selected())});
})();
